import axios from 'axios'

const API_URL = 'http://localhost:3000/api'

// Configuration d'Axios pour les logs et CORS
axios.defaults.withCredentials = true

// Intercepteur pour les logs
axios.interceptors.request.use(request => {
  console.log('Request:', {
    method: request.method,
    url: request.url,
    data: request.data,
    headers: request.headers
  })
  return request
})

axios.interceptors.response.use(
  response => {
    console.log('Response:', {
      status: response.status,
      data: response.data,
      headers: response.headers
    })
    return response
  },
  error => {
    console.error('Error:', {
      message: error.message,
      response: error.response?.data,
      status: error.response?.status,
      headers: error.response?.headers
    })
    return Promise.reject(error)
  }
)

// Intercepteur pour ajouter le token aux requêtes
axios.interceptors.request.use(config => {
  const token = localStorage.getItem('token')
  if (token) {
    config.headers.Authorization = `Bearer ${token}`
  }
  return config
})

export default {
  namespaced: true,

  state: {
    token: localStorage.getItem('token') || null,
    user: JSON.parse(localStorage.getItem('user')) || null,
    error: null
  },

  mutations: {
    SET_TOKEN(state, token) {
      state.token = token
      if (token) {
        localStorage.setItem('token', token)
      } else {
        localStorage.removeItem('token')
      }
    },

    SET_USER(state, user) {
      state.user = user
      if (user) {
        localStorage.setItem('user', JSON.stringify(user))
      } else {
        localStorage.removeItem('user')
      }
    },

    SET_ERROR(state, error) {
      state.error = error
    },

    CLEAR_AUTH(state) {
      state.token = null
      state.user = null
      state.error = null
      localStorage.removeItem('token')
      localStorage.removeItem('user')
    }
  },

  actions: {
    async login({ commit }, credentials) {
      try {
        const response = await axios.post(`${API_URL}/auth/login`, credentials)
        const { token, user } = response.data

        commit('SET_TOKEN', token)
        commit('SET_USER', user)
        commit('SET_ERROR', null)

        return response.data
      } catch (error) {
        console.error('Erreur lors de la connexion:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Erreur lors de la connexion'
        commit('SET_ERROR', errorMessage)
        throw errorMessage
      }
    },

    async register({ commit }, userData) {
      try {
        const response = await axios.post(`${API_URL}/auth/register`, userData)
        commit('SET_ERROR', null)
        return response.data
      } catch (error) {
        console.error('Erreur lors de l\'inscription:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Erreur lors de l\'inscription'
        commit('SET_ERROR', errorMessage)
        throw errorMessage
      }
    },

    logout({ commit }) {
      commit('CLEAR_AUTH')
    }
  }
}
